import sys, json, urllib.request, base64, os
sys.stdout.reconfigure(encoding="utf-8")

BASE = "http://127.0.0.1:8099/api/v3.0"
SHOT = r"D:\repository\苏州市房地产监测V3-wt-bug6073\.pua\shots"


def post(url, obj, token=None):
    h = {"Content-Type": "application/json"}
    if token:
        h["Authorization"] = "Bearer " + token
    req = urllib.request.Request(url, data=json.dumps(obj).encode(), headers=h)
    try:
        return json.loads(urllib.request.urlopen(req, timeout=20).read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        return {"httpError": e.code, "body": e.read().decode("utf-8", "ignore")[:200]}


if __name__ == "__main__":
    cmd = sys.argv[1]
    if cmd == "cap":
        c = post(BASE + "/code", {})
        open(os.path.join(SHOT, "trycap.jpg"), "wb").write(base64.b64decode(c["data"]))
        open(os.path.join(SHOT, "tryuuid.txt"), "w").write(c["uuid"])
        print("UUID", c["uuid"], "captcha_field", repr(c.get("captcha")))
    elif cmd == "login":
        uuid = open(os.path.join(SHOT, "tryuuid.txt")).read().strip()
        r = post(BASE + "/security/auth/userLogin",
                 {"username": "zsbase", "password": "ZS001Aa!", "code": sys.argv[2], "uuid": uuid})
        print(json.dumps(r, ensure_ascii=False)[:200])
        if r.get("code") == 200:
            open(os.path.join(SHOT, "token.txt"), "w").write((r.get("data") or {}).get("accessToken", ""))
            print("TOKEN saved")
    elif cmd == "probe-menu":
        tok = open(os.path.join(SHOT, "token.txt")).read().strip()
        for url in ["/system/menu/getRouters", "/getRouters", "/menu/getRouters"]:
            print(url, json.dumps(post(BASE + url, {}, tok), ensure_ascii=False)[:150])

