// 用 Node + CryptoJS（项目 index.html 全局引入的那份）复现 encryptPassword，然后直接打接口。
// 用法： node login-node.mjs            -> 只取验证码，保存图片与 uuid
//        node login-node.mjs <ans>      -> 用 <ans> 提交登录
import fs from 'fs'
import path from 'path'
import crypto from 'crypto'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SHOT = path.resolve(__dirname, '../.pua/shots')
const BASE = 'http://127.0.0.1:8099/api/v3.0'

// 纯 Node 实现 CryptoJS 等价 AES-CBC/Pkcs7（key/iv 为 Utf8），
// 注意 CryptoJS 允许任意长度 key，内部按 sigBytes 取用；这里是 20 字节 key，
// CryptoJS 实际会把 key 按 word 处理 -> 我们用同样 20 字节原始 key 走 AES-192? 
// 为完全对齐，改用 node-forge? 先直接用 CryptoJS 包。
import CryptoJS from 'crypto-js'

function encryptPassword(plain) {
  if (plain == null || plain === '') return plain
  const key = CryptoJS.enc.Utf8.parse('A-16-Byte-keyValA-16-Byte-keyVal')
  const iv = CryptoJS.enc.Utf8.parse('A-16-Byte-String')
  return CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(String(plain)), key, {
    iv, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7
  }).toString()
}

async function post(url, obj, token) {
  const headers = { 'Content-Type': 'application/json' }
  if (token) headers['Authorization'] = 'Bearer ' + token
  const r = await fetch(url, { method: 'POST', headers, body: JSON.stringify(obj) })
  const text = await r.text()
  try { return JSON.parse(text) } catch { return { raw: text.slice(0, 200), status: r.status } }
}

const cmd = process.argv[2]
if (!cmd || cmd === 'cap') {
  const c = await post(BASE + '/code', {})
  fs.writeFileSync(path.join(SHOT, 'trycap.jpg'), Buffer.from(c.data, 'base64'))
  fs.writeFileSync(path.join(SHOT, 'tryuuid.txt'), c.uuid)
