// 用项目自带的 crypto-js.min.js（浏览器版，挂到 global）复现 encryptPassword 并直接打登录接口。
// 用法：node login-cjs-6073.mjs            -> 取验证码，存图+uuid
//       node login-cjs-6073.mjs <answer>   -> 用 <answer> 提交登录
import fs from 'fs'
import path from 'path'
import vm from 'vm'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const SHOT = path.resolve(__dirname, '../../../.pua/shots')
const BASE = 'http://127.0.0.1:8099/api/v3.0'
const libPath = path.resolve(__dirname, '../../public/assets/js/crypto-js.min.js')

// 在隔离上下文执行浏览器版 crypto-js，取全局 CryptoJS
const sandbox = { window: {}, self: {}, globalThis: {} }
sandbox.window = sandbox
sandbox.self = sandbox
vm.createContext(sandbox)
vm.runInContext(fs.readFileSync(libPath, 'utf8'), sandbox)
const CryptoJS = sandbox.CryptoJS || sandbox.window.CryptoJS
if (!CryptoJS) { console.error('CryptoJS load failed'); process.exit(1) }

function encryptPassword(plain) {
  if (plain == null || plain === '') return plain
  const key = CryptoJS.enc.Utf8.parse('A-16-Byte-keyValA-16-Byte-keyVal')
  const iv = CryptoJS.enc.Utf8.parse('A-16-Byte-String')
  return CryptoJS.AES.encrypt(CryptoJS.enc.Utf8.parse(String(plain)), key, {
    iv, mode: CryptoJS.mode.CBC, padding: CryptoJS.pad.Pkcs7
  }).toString()
}

async function post(url, obj) {
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(obj) })
  const t = await r.text()
  try { return JSON.parse(t) } catch { return { status: r.status, raw: t.slice(0, 200) } }
}

const cmd = process.argv[2]
if (!cmd) {
  const c = await post(BASE + '/code', {})
  fs.writeFileSync(path.join(SHOT, 'trycap.jpg'), Buffer.from(c.data, 'base64'))
  fs.writeFileSync(path.join(SHOT, 'tryuuid.txt'), c.uuid)
  console.log('UUID', c.uuid, 'captcha_field', JSON.stringify(c.captcha))
} else {
  const uuid = fs.readFileSync(path.join(SHOT, 'tryuuid.txt'), 'utf8').trim()
  const r = await post(BASE + '/security/auth/userLogin', { username: 'zsbase', password: encryptPassword('ZS001Aa!'), code: cmd, uuid })
  console.log('LOGIN', JSON.stringify(r).slice(0, 300))
  if (r.code === 200) { fs.writeFileSync(path.join(SHOT, 'token.txt'), (r.data || {}).accessToken || ''); console.log('TOKEN saved') }
}

